-- Real font metrics for the fake client's font strings, and the layout checks scripts/measure-layout.sh runs.
--
-- The fake client (spec/support/widgets.lua) measures every string at 6 units a byte. This module gives a font string
-- the advance widths of the face it is set in, from the bundled TTFs under addons/Pagle/media/fonts/ (advances.lua,
-- generated by scripts/measure-layout.py advances), so the addon's own fitting (GetStringWidth, IsTruncated) runs on
-- widths close to the client's, and then reads back what each shown surface draws.
--
--   local RealFont = dofile("scripts/measure-layout/realfont.lua")
--   RealFont.patch(fontString)   -- one font string measures in its real face; nothing else changes
--   RealFont.install()           -- every font string the fake client makes from here on (the harness's helper)
--
-- What it can't know: kerning (advances are summed), the client's exact line height (the face's ascent plus descent,
-- or MEASURE_LINE times the size), faces the add-on doesn't bundle (the client's own, such as FRIZQT__ and the ruRU
-- faces, measure in Marcellus as a stand-in) and glyphs a face lacks (Cyrillic in the Latin faces is estimated from a
-- Latin look-alike). A finding that rests on any of those is marked estimated. Under the pseudo-locale
-- (MEASURE_LANG=pseudo), a glyph a face lacks measures as the face's notdef box, which is what the client draws for it.

local RealFont = {}

---@diagnostic disable-next-line: undefined-global -- busted runs on stock Lua 5.1; the WoW client has no dofile
local ADVANCES = dofile("scripts/measure-layout/advances.lua")

-- The face that stands in for a font file the add-on doesn't bundle (the client's own faces).
local STAND_IN = "Marcellus-Regular.ttf"
-- Lines are the face's ascent plus descent tall, unless MEASURE_LINE gives one factor of the size for every face.
---@diagnostic disable-next-line: undefined-global -- busted runs on stock Lua 5.1; the WoW client has no os
local LINE = tonumber(os.getenv("MEASURE_LINE") or "")
-- Whether a glyph a face lacks measures as its notdef box: the pseudo-locale's run (#592), whose Cyrillic look-alikes
-- and padding letters the Latin faces draw as boxes, about two thirds of an em in IM Fell.
---@diagnostic disable-next-line: undefined-global -- busted runs on stock Lua 5.1; the WoW client has no os
local BOXES = os.getenv("MEASURE_LANG") == "pseudo"
-- The size a font object the fakes don't size draws at, as the client's GameFontNormal.
local DEFAULT_SIZE = 12

-- Each codepoint in the UTF-8 string `s`, in order.
---@param s string
---@return integer[]
local function codepoints(s)
	local out = {}
	for ch in s:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
		local c = ch:byte(1)
		local cp
		if c < 0x80 then
			cp = c
		elseif c < 0xE0 then
			cp = (c - 0xC0) * 64 + (ch:byte(2) - 0x80)
		elseif c < 0xF0 then
			cp = (c - 0xE0) * 4096 + (ch:byte(2) - 0x80) * 64 + (ch:byte(3) - 0x80)
		else
			cp = 0xFFFD
		end
		out[#out + 1] = cp
	end
	return out
end

-- The private-use codepoint that stands for an inline texture or atlas (|T…|t, |A…|a): one em wide.
local ICON = 0xE000

-- `text` as the client draws its characters: colour codes and hyperlink markup gone, "||" one bar, each inline
-- texture one ICON.
---@param text string
---@return string
function RealFont.plain(text)
	return (
		text:gsub("||", "\1")
			:gsub("|c%x%x%x%x%x%x%x%x", "")
			:gsub("|r", "")
			:gsub("|H.-|h(.-)|h", "%1")
			:gsub("|T.-|t", "\238\128\128")
			:gsub("|A.-|a", "\238\128\128")
			:gsub("\1", "|")
	)
end

--- The face file and size a font string draws in, and whether the face is a stand-in.
---@param region table
---@return string file
---@return number size
---@return boolean standIn
function RealFont.face(region)
	local font = region.font
	local object = region.fontObject
	if not font and type(object) == "table" then
		font = object.font
	end
	local file, size = nil, DEFAULT_SIZE
	if font then
		file = tostring(font[1] or ""):match("([^\\/]+)$")
		size = tonumber(font[2]) or DEFAULT_SIZE
	end
	if file and ADVANCES.faces[file] then
		return file, size, false
	end
	return STAND_IN, size, true
end

--- The width of `text` in face `file` at `size`, and whether any of it was estimated (a glyph the face lacks).
---@param text string
---@param file string
---@param size number
---@return number width
---@return boolean estimated
function RealFont.width(text, file, size)
	local face = ADVANCES.faces[file]
	local widths, estimated = face.advances, face.estimated
	local total, guessed = 0, false
	for _, cp in ipairs(codepoints(RealFont.plain(text or ""))) do
		local advance = widths[cp]
		if cp == ICON then
			advance = 1000
		elseif BOXES and (not advance or estimated[cp]) and cp > 32 then
			advance = face.notdef
		elseif not advance then
			advance, guessed = 500, true
		elseif estimated[cp] then
			guessed = true
		end
		total = total + advance
	end
	return total * size / 1000, guessed
end

--- One line's height in face `file` at `size`.
---@param file string
---@param size number
---@return number
function RealFont.lineHeight(file, size)
	return (LINE or ADVANCES.faces[file].line) * size
end

-- `text` broken into the lines the client would draw it in at most `width` wide: at "\n", then greedily at spaces.
-- A word wider than `width` stays one line (the client would break it inside the word).
---@param text string
---@param file string
---@param size number
---@param width number
---@return string[]
local function wrap(text, file, size, width)
	local lines = {}
	for paragraph in (text .. "\n"):gmatch("(.-)\n") do
		local line = ""
		for word in paragraph:gmatch("%S+") do
			local try = line == "" and word or line .. " " .. word
			if line ~= "" and RealFont.width(try, file, size) > width then
				lines[#lines + 1] = line
				line = word
			else
				line = try
			end
		end
		lines[#lines + 1] = line
	end
	return lines
end

-- A size the fake lays out from the region's anchors (GetWidth, GetHeight), or nil while it has none.
---@param region table
---@param method string
---@return number?
local function laidOut(region, method)
	local ok, size = pcall(region[method], region)
	if ok and type(size) == "number" and size > 0 then
		return size
	end
	return nil
end

--- How a font string lays out its text in its real face: its lines, its natural (one-line) width, the widest line it
--- shows, its height, and whether the client would cut it, with why.
---@class RealFontLayout
---@field lines string[]
---@field natural number
---@field shown number
---@field height number
---@field cut string? why it is cut: "wider than its box", "more than N lines", "taller than its box"
---@field file string
---@field size number
---@field estimated boolean

---@param region table
---@return RealFontLayout
function RealFont.layout(region)
	local text = RealFont.plain(region.text or "")
	local file, size, standIn = RealFont.face(region)
	local natural, estimated = RealFont.width(text, file, size)
	estimated = estimated or standIn
	local width, height = laidOut(region, "GetWidth"), laidOut(region, "GetHeight")
	local lineHeight = RealFont.lineHeight(file, size)
	local lines, cut
	if width and region.wordWrap ~= false then
		lines = wrap(text, file, size, width)
		local maxLines = region.maxLines or 0
		if maxLines > 0 and #lines > maxLines then
			cut = ("more than %d line%s"):format(maxLines, maxLines == 1 and "" or "s")
			lines = { unpack(lines, 1, maxLines) }
		elseif height and #lines > 1 and #lines * lineHeight > height + lineHeight / 2 then
			cut = ("%d lines taller than its box (%.0f)"):format(#lines, height)
		end
		for _, line in ipairs(lines) do
			if not cut and RealFont.width(line, file, size) > width + 0.5 then
				cut = "a word wider than its box"
			end
		end
	else
		lines = {}
		for line in (text .. "\n"):gmatch("(.-)\n") do
			lines[#lines + 1] = line
		end
		if width then
			for _, line in ipairs(lines) do
				if RealFont.width(line, file, size) > width + 0.5 then
					cut = "wider than its box"
				end
			end
		end
	end
	local shown = 0
	for _, line in ipairs(lines) do
		shown = math.max(shown, (RealFont.width(line, file, size)))
	end
	if width then
		shown = math.min(shown, width)
	end
	return {
		lines = lines,
		natural = natural,
		shown = shown,
		height = #lines * lineHeight,
		cut = cut,
		file = file,
		size = size,
		estimated = estimated,
	}
end

--- Makes one fake font string measure in its real face: GetStringWidth, GetUnboundedStringWidth, GetStringHeight and
--- IsTruncated answer from RealFont.layout. Returns it; any other widget comes back as it was.
---@param widget table
---@return table
function RealFont.patch(widget)
	if widget.kind ~= "FontString" then
		return widget
	end
	function widget:GetStringWidth()
		return RealFont.layout(self).shown
	end
	function widget:GetUnboundedStringWidth()
		return RealFont.layout(self).natural
	end
	function widget:GetStringHeight()
		return RealFont.layout(self).height
	end
	function widget:IsTruncated()
		return RealFont.layout(self).cut ~= nil
	end
	return widget
end

--- Makes every font string the fake client makes from now on measure in its real face (RealFont.patch): wraps the
--- global dofile so that each load of spec/support/widgets.lua makes its widgets through RealFont.patch. Call it
--- before spec/support/addon.lua loads; spec/support/ itself is unchanged, so every spec keeps 6 units a byte.
function RealFont.install()
	---@diagnostic disable-next-line: undefined-global -- busted runs on stock Lua 5.1; the WoW client has no dofile
	local realDofile = dofile
	rawset(_G, "dofile", function(path, ...)
		local result = realDofile(path, ...)
		-- The path addon.lua and client.lua load it by.
		if path == "spec/support/widgets.lua" and type(result) == "table" and not result.realFont then
			result.realFont = true
			local newWidget = result.newWidget
			result.newWidget = function(kind, parent)
				return RealFont.patch(newWidget(kind, parent))
			end
		end
		return result
	end)
end

-- A side of a SetPoint point: "LEFT", "RIGHT" or nil for the centre (horizontal); "TOP", "BOTTOM" or nil (vertical).
local function sides(point)
	return point:find("LEFT") and "LEFT" or point:find("RIGHT") and "RIGHT" or nil,
		point:find("TOP") and "TOP" or point:find("BOTTOM") and "BOTTOM" or nil
end

--- `region`'s scale times its parents', as the client's GetEffectiveScale.
---@param region table
---@return number
function RealFont.scale(region)
	local scale, r = 1, region
	while r do
		scale = scale * (r.scale or 1)
		r = r.parent
	end
	return scale
end

--- Where `region` sits on the screen, as { left, top, right, bottom } in units from the screen's top left (y down),
--- from its anchors, as the client lays it out; nil if any anchor leads nowhere (an unanchored frame). `memo` keeps
--- the regions already placed. A scroll frame's child sits at its top left, scrolled by its vertical scroll. A
--- region's size and its anchors' offsets are in its own scale (RealFont.scale), as the client's.
---@param region table
---@param memo table
---@return number[]?
function RealFont.rect(region, memo)
	if memo[region] ~= nil then
		return memo[region] or nil
	end
	memo[region] = false -- a cycle leads nowhere
	local points = region.points or {}
	if #points == 0 and region.parent and region.parent.scrollChild == region then
		points = { { "TOPLEFT", region.parent, "TOPLEFT", 0, region.parent.verticalScroll or 0 } }
	end
	if #points == 0 then
		if region.parent == nil and region.width and region.height then -- UIParent, the screen
			memo[region] = { 0, 0, region.width, region.height }
			return memo[region]
		end
		return nil
	end
	local scale = RealFont.scale(region)
	local left, right, top, bottom, centerX, centerY
	for _, anchor in ipairs(points) do
		local relativeTo, relativePoint, x, y
		if type(anchor[2]) == "number" or anchor[2] == nil then
			relativeTo, relativePoint, x, y = region.parent, anchor[1], anchor[2] or 0, anchor[3] or 0
		else
			relativeTo, relativePoint, x, y = anchor[2], anchor[3] or anchor[1], anchor[4] or 0, anchor[5] or 0
		end
		local relative = type(relativeTo) == "table" and RealFont.rect(relativeTo, memo)
		if not relative then
			return nil
		end
		local h, v = sides(relativePoint)
		local px = (h == "LEFT" and relative[1] or h == "RIGHT" and relative[3] or (relative[1] + relative[3]) / 2)
			+ x * scale
		local py = (v == "TOP" and relative[2] or v == "BOTTOM" and relative[4] or (relative[2] + relative[4]) / 2)
			- y * scale
		h, v = sides(anchor[1])
		if h == "LEFT" then
			left = px
		elseif h == "RIGHT" then
			right = px
		else
			centerX = px
		end
		if v == "TOP" then
			top = py
		elseif v == "BOTTOM" then
			bottom = py
		else
			centerY = py
		end
	end
	local width, height = region.width or 0, region.height or 0
	if region.kind == "FontString" then
		local layout = RealFont.layout(region)
		width = width > 0 and width or layout.natural
		height = height > 0 and height or layout.height
	end
	width, height = width * scale, height * scale
	left = left or (right and right - width) or (centerX and centerX - width / 2)
	right = right or (left and left + width)
	top = top or (bottom and bottom - height) or (centerY and centerY - height / 2)
	bottom = bottom or (top and top + height)
	if not (left and right and top and bottom) then
		return nil
	end
	memo[region] = { left, top, right, bottom }
	return memo[region]
end

--- Where a font string's ink sits on the screen: its widest shown line placed by its justification across its box,
--- its lines' height placed by its vertical justification in it.
---@param region table
---@param memo table
---@return number[]?
function RealFont.inked(region, memo)
	local box = RealFont.rect(region, memo)
	if not box then
		return nil
	end
	local layout = RealFont.layout(region)
	local scale = RealFont.scale(region)
	local width, height = layout.shown * scale, layout.height * scale
	local left = box[1]
	if region.justifyH == "RIGHT" then
		left = box[3] - width
	elseif region.justifyH == "CENTER" or (region.justifyH == nil and box[3] - box[1] > width + 0.5) then
		-- The client centres a font string's text unless SetJustifyH says otherwise.
		left = (box[1] + box[3] - width) / 2
	end
	local top = box[2]
	local room = box[4] - box[2]
	if room > height then
		if region.justifyV == "BOTTOM" then
			top = box[4] - height
		elseif region.justifyV ~= "TOP" then
			top = top + (room - height) / 2
		end
	end
	return { left, top, left + width, top + height }
end

return RealFont
